(()=>{const out={};for(const kind of ['webgl','webgl2']){const g=new OffscreenCanvas(4,4).getContext(kind),t=g.createTexture(),r=out[kind]={fresh:g.isTexture(t),tag:Object.prototype.toString.call(t),active:g.getParameter(g.ACTIVE_TEXTURE)};g.bindTexture(g.TEXTURE_2D,t);r.bound=g.isTexture(t);r.identity=g.getParameter(g.TEXTURE_BINDING_2D)===t;r.defaults=[g.TEXTURE_MAG_FILTER,g.TEXTURE_MIN_FILTER,g.TEXTURE_WRAP_S,g.TEXTURE_WRAP_T].map(p=>g.getTexParameter(g.TEXTURE_2D,p));g.texParameteri(g.TEXTURE_2D,g.TEXTURE_MIN_FILTER,g.NEAREST);g.activeTexture(g.TEXTURE1);r.second=g.getParameter(g.TEXTURE_BINDING_2D);g.bindTexture(g.TEXTURE_2D,t);r.shared=g.getTexParameter(g.TEXTURE_2D,g.TEXTURE_MIN_FILTER);g.bindTexture(g.TEXTURE_CUBE_MAP,t);r.targetError=g.getError();g.texImage2D(g.TEXTURE_2D,0,g.RGBA,2,2,0,g.RGBA,g.UNSIGNED_BYTE,new Uint8Array(16));r.upload=g.getError();g.texSubImage2D(g.TEXTURE_2D,0,1,1,1,1,g.RGBA,g.UNSIGNED_BYTE,new Uint8Array([10,20,30,40]));r.sub=g.getError();g.texSubImage2D(g.TEXTURE_2D,0,2,1,1,1,g.RGBA,g.UNSIGNED_BYTE,new Uint8Array(4));r.bounds=g.getError();g.texParameteri(g.TEXTURE_2D,g.TEXTURE_WRAP_S,0);r.enumError=g.getError();g.deleteTexture(t);r.deleted=g.isTexture(t);r.detached=g.getParameter(g.TEXTURE_BINDING_2D);g.activeTexture(g.TEXTURE0);r.detachedOther=g.getParameter(g.TEXTURE_BINDING_2D);r.error=g.getError()}return out})()
